/* Original, lightweight vector assets. The user requested in-project SVG artwork. */
(function(root){
  const wrap=(body,view='0 0 100 100',cls='')=>`<svg class="vector-art ${cls}" viewBox="${view}" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">${body}</svg>`;
  function product(name,cls=''){
    let body='';
    if(/Queso/.test(name))body='<ellipse cx="51" cy="82" rx="38" ry="7" fill="#213f3b" opacity=".1"/><path d="M15 44 63 21 87 43v35H15z" fill="#f6c761" stroke="#a97937" stroke-width="2"/><path d="m15 44 48-23 24 22-48 19z" fill="#ffdf8a"/><path d="M39 62v16H15V44z" fill="#edb44c"/><g fill="#dba348"><ellipse cx="52" cy="38" rx="6" ry="4"/><ellipse cx="68" cy="45" rx="5" ry="3"/><circle cx="55" cy="68" r="5"/><circle cx="76" cy="59" r="4"/><circle cx="26" cy="67" r="4"/></g>';
    else if(/Helado/.test(name))body='<path d="m30 47 20 43 21-43" fill="#deb079" stroke="#a97f49" stroke-width="2"/><path d="m37 58 25 18m-18 9 19-27M34 69l30-9" stroke="#b88b55" stroke-width="2"/><path d="M23 48c-7-17 8-23 16-23-1-21 29-20 29 1 18 1 20 17 9 25-9 7-15-3-24 2s-20 2-30-5" fill="#f9d3d4" stroke="#c9949a" stroke-width="2"/><circle cx="51" cy="16" r="5" fill="#d26e65"/>';
    else if(/Yogurt/.test(name))body='<ellipse cx="49" cy="82" rx="32" ry="6" fill="#213f3b" opacity=".1"/><path d="m22 32 8 44q20 14 40 0l8-44" fill="#fff7e2" stroke="#9fabc3" stroke-width="2"/><path d="m26 44 5 26q19 9 38 0l5-26" fill="#b9afd9"/><ellipse cx="50" cy="32" rx="29" ry="8" fill="#e1d8ef" stroke="#958aaf" stroke-width="2"/><path d="M38 58q12-13 24 0-12 12-24 0" fill="#fff9e7"/><path d="m65 26 9-17" stroke="#8a9fb2" stroke-width="4" stroke-linecap="round"/>';
    else if(/Mantequilla/.test(name))body='<path d="m13 40 49-16 27 20-48 17z" fill="#ffe5a0" stroke="#c3a162" stroke-width="2"/><path d="M13 40v30l28 17V61z" fill="#ebbe6a"/><path d="m41 61 48-17v29L41 87z" fill="#f4d17f"/><path d="m32 34 25-8 25 20-23 8z" fill="#fff9e5"/><path d="M59 54v27l23-8V46z" fill="#faf2da"/>';
    else if(/Postre/.test(name))body='<ellipse cx="50" cy="77" rx="39" ry="11" fill="#c8dce1"/><path d="m24 68 8-39h36l9 39q-26 18-53 0" fill="#f2c888" stroke="#c4945d" stroke-width="2"/><ellipse cx="50" cy="29" rx="18" ry="7" fill="#9f6550"/><path d="M34 34v25m12-21v27m13-27v26m9-29 3 26" stroke="#f9dba7" stroke-width="3"/>';
    else {const color=/chocolatada/.test(name)?'#95705d':/Kumis|fermentada/.test(name)?'#8bad78':'#6aa4bb';body=`<ellipse cx="50" cy="88" rx="26" ry="5" fill="#213f3b" opacity=".1"/><path d="m29 29 11-17h21l11 17v56H29z" fill="#fffcf0" stroke="#6c969b" stroke-width="2"/><path d="m29 29 11-17v18H29m11 0h32L61 12H40" fill="#cbe1e3"/><path d="M29 44h43v29H29z" fill="${color}"/><path d="M50 50c-3 5-10 10-7 15 4 7 16 2 13-4z" fill="#fff9e8"/><path d="M61 30v54" stroke="#dbe7df" stroke-width="3"/><path d="M41 12h20" stroke="${color}" stroke-width="5"/>`;}
    return wrap(body,'0 0 100 100','product-drawing '+cls);
  }
  function machine(m=0){return wrap(`<ellipse cx="92" cy="146" rx="76" ry="10" fill="#143b39" opacity=".12"/><path d="M15 75V29h40m86 63V49h24v-25" stroke="#8faeb0" stroke-width="7" stroke-linejoin="round"/><path d="M40 47v85m96-85v85" stroke="#55767a" stroke-width="10"/><rect x="29" y="37" width="119" height="99" rx="23" fill="#c8dde0" stroke="#547e83" stroke-width="3"/><ellipse cx="88" cy="38" rx="59" ry="14" fill="#edf3e8" stroke="#547e83" stroke-width="3"/><path d="M48 58v57" stroke="#eaf2eb" stroke-width="11" stroke-linecap="round"/><rect x="76" y="60" width="52" height="47" rx="7" fill="#205b58"/><rect x="82" y="67" width="40" height="19" rx="3" fill="#b6d7b8"/><path d="m87 77 7-5 6 8 7-5h10" stroke="#438874" stroke-width="2"/><circle class="machine-light" cx="88" cy="96" r="4" fill="#d8bc72"/><circle cx="104" cy="96" r="3" fill="#d9e9d7"/><circle cx="118" cy="96" r="3" fill="#d9e9d7"/><path d="M57 138v8m63-8v8" stroke="#365f62" stroke-width="6"/><text x="143" y="126" fill="#527d82" font-family="sans-serif" font-size="12" font-weight="bold">${String.fromCharCode(65+m)}</text>`,'0 0 185 165','machine-drawing');}
  function truck(){return wrap('<ellipse cx="89" cy="128" rx="77" ry="9" fill="#1e4245" opacity=".1"/><rect x="11" y="41" width="100" height="72" rx="6" fill="#f9f1d7" stroke="#4e807f" stroke-width="3"/><path d="M112 66h29l29 31v16h-58z" fill="#659c9d" stroke="#376c70" stroke-width="3"/><path d="M123 74h15l18 22h-33z" fill="#d9edf0"/><path d="M13 97h96" stroke="#b7d3c1" stroke-width="17"/><circle cx="42" cy="115" r="15" fill="#30555a"/><circle cx="42" cy="115" r="7" fill="#b8c8c4"/><circle cx="140" cy="115" r="15" fill="#30555a"/><circle cx="140" cy="115" r="7" fill="#b8c8c4"/><path d="M60 53c-2 10-14 15-10 24 5 13 25 8 23-4-1-7-10-13-13-20" fill="#85bcb8"/>','0 0 185 150','truck-drawing');}
  function crate(){return wrap('<path d="m15 36 36-17 36 17-36 18z" fill="#ecd49b"/><path d="M15 36v44l36 15V54z" fill="#cfa874"/><path d="m51 54 36-18v44L51 95z" fill="#e1bd83"/><path d="m38 24 34 18v21l-12 6V48L26 31" fill="#f5e6c0"/><path d="M24 59v12m8-9v12m30 0 18-8" stroke="#987447" stroke-width="3"/>');}
  function academy(){return wrap('<path d="M13 22q22-9 37 2 20-11 38-2v59q-20-8-38 1-17-10-37-1z" fill="#fff7e1" stroke="#518586" stroke-width="3"/><path d="M50 25v57" stroke="#b0d0cc" stroke-width="3"/><path d="M23 37h17m-17 11h17m-17 11h12M61 40h17m-17 11h17m-17 11h12" stroke="#8eb1af" stroke-width="3" stroke-linecap="round"/><path d="M70 13v17l6-4 6 4V11" fill="#e4b85b"/>');}
  function medal(){return wrap('<path d="m27 12 8 34h30l8-34H57l-7 20-7-20z" fill="#4e8c94"/><path d="m29 12 8 30m33-30-8 30" stroke="#b2d7d8" stroke-width="4"/><circle cx="50" cy="62" r="30" fill="#e8bd61" stroke="#b68c43" stroke-width="3"/><circle cx="50" cy="62" r="24" stroke="#fff0b6" stroke-width="2"/><path d="m50 44 5 11 13 2-9 9 2 13-11-6-11 6 2-13-9-9 13-2z" fill="#fff1bd"/>','0 0 100 100','medal-drawing');}
  function worker(){return wrap('<path d="M20 93V72q0-14 16-19h29q15 5 15 19v21" fill="#578e94"/><path d="M36 56v37h28V56" fill="#efc26a"/><circle cx="50" cy="33" r="22" fill="#edc4a3"/><path d="M24 29q0-25 26-25t26 25z" fill="#edbd57"/><path d="M20 28h60" stroke="#bd9042" stroke-width="5" stroke-linecap="round"/><circle cx="42" cy="36" r="2" fill="#355559"/><circle cx="58" cy="36" r="2" fill="#355559"/><path d="M44 46q6 5 12 0" stroke="#af7562" stroke-width="2"/><path d="M37 78h27" stroke="#c7984f" stroke-width="2"/>','0 0 100 100','worker-drawing');}
  function scene(){return `<div class="factory-scene" aria-label="Línea de producción de La Vía Láctea"><div class="scene-pipes"></div><div class="scene-station"><span>01 · RECEPCIÓN</span>${product('Leche fresca')}</div><div class="scene-station"><span>02 · PASTEURIZACIÓN</span>${machine()}</div><div class="scene-station"><span>03 · DESPACHO</span>${truck()}</div><div class="scene-belt"><i></i><i></i><i></i><i></i><i></i></div><div class="scene-worker">${worker()}</div></div>`;}
  root.DairyArt={product,machine,truck,crate,academy,medal,worker,scene};
})(globalThis);
